// Normaliza el payload entrante a la forma {tenantId, phone, messageText, messageId, receivedAt}.
// Ajusta el mapeo segun el formato real del webhook de WhatsApp Cloud API.
const body = $json.body ?? $json;
const entry = body.entry?.[0]?.changes?.[0]?.value ?? {};
const m = entry.messages?.[0];
if (!m || m.type !== 'text') { return []; }
return [{ json: {
  tenantId: $env.TENANT_ID || body.tenantId,
  phone: m.from,
  messageText: m.text.body,
  messageId: m.id,
  receivedAt: m.timestamp ? new Date(Number(m.timestamp) * 1000).toISOString() : new Date().toISOString(),
} }];

